DROP TRIGGER IF EXISTS trg_sync_flock_from_broiler ON public.broiler_batches; CREATE TRIGGER trg_sync_flock_from_broiler AFTER INSERT OR UPDATE OR DELETE ON public.broiler_batches FOR EACH ROW EXECUTE FUNCTION public.sync_flock_info_from_batch(); UPDATE public.layer_batches SET current_bird_count = current_bird_count WHERE status = 'active'; UPDATE public.broiler_batches SET current_bird_count = current_bird_count WHERE status = 'active';